import{_ as i}from"./chunks/cg-mblb5.6f27f453.js";import{_ as a,o as p,c as t,O as e}from"./chunks/framework.b9c6cb60.js";const o="/assets/cg-ht1.6d11c2c7.png",r="/assets/cg-ht4.ff30dffd.png",s="/assets/htAIpb1.fcd47206.png",h="/assets/htAIpb2.55a16620.png",u="/assets/htAIpb3.1f3f6baa.png",n="/assets/cg-ht2.4f1df9e6.png",c="/assets/cg-ht3.c7b742d5.png",d="/assets/cg-ht1-1.83c6e704.png",A=JSON.parse('{"title":"合同列表","description":"","frontmatter":{},"headers":[],"relativePath":"采购管理/合同列表.md","filePath":"采购管理/合同列表.md"}'),_={name:"采购管理/合同列表.md"};function q(m,l,b,f,g,k){return p(),t("div",null,l[0]||(l[0]=[e('<h1 id="合同列表" tabindex="-1">合同列表 <a class="header-anchor" href="#合同列表" aria-label="Permalink to &quot;合同列表&quot;">​</a></h1><blockquote><p>&quot;合同列表“位于&quot;采购管理板块，在&quot;合同列表&quot;可维护相对应的合同单，可添加收款，提交发票，收货，查看详情</p></blockquote><h4 id="_1-新增合同" tabindex="-1">1.新增合同 <a class="header-anchor" href="#_1-新增合同" aria-label="Permalink to &quot;1.新增合同&quot;">​</a></h4><ul><li><p>新增合同的方式</p><p>-直接新建采购合同，合同信息由采购人员编辑</p><p>-将报价单转为合同，信息由采购人员编辑</p></li></ul><h4 id="_2-收货" tabindex="-1">2.收货 <a class="header-anchor" href="#_2-收货" aria-label="Permalink to &quot;2.收货&quot;">​</a></h4><ul><li><p>当销售方和采购方均是系统内的企业时，对方发货后采购合同显示收货按钮</p></li><li><p>点击收货按钮，填写收货量、送检量、需求完成时间</p><p>-可一键点击设置收货量</p><p>-采购所签合同时填写的内部型号如果有质检项，收货时可送检（所送检的产品将到入库检安排列表中由主任进行分发检验</p><p>-也可不送检直接签收到入库列表中进行入库</p></li></ul><h4 id="_3-删除功能" tabindex="-1">3. 删除功能 <a class="header-anchor" href="#_3-删除功能" aria-label="Permalink to &quot;3. 删除功能&quot;">​</a></h4><ul><li>未签章的合同支持删除</li><li>报价单转入的合同无法删除</li></ul><h4 id="_4-合同状态" tabindex="-1">4.合同状态： <a class="header-anchor" href="#_4-合同状态" aria-label="Permalink to &quot;4.合同状态：&quot;">​</a></h4><ul><li>已签章：（深色代表双方都签章，浅色代表只有一方签章）</li><li>未签章：在合同页面新增的合同没签章之前可以删除，报价单流转过来的合同不支持删除</li></ul><p><img src="'+o+'" alt="如图所示"></p><h4 id="_5-详情" tabindex="-1">5.详情 <a class="header-anchor" href="#_5-详情" aria-label="Permalink to &quot;5.详情&quot;">​</a></h4><ul><li><p>生成二维码</p><p>-合同签署后，页面详情会生成二维码，通过用户端app可以进行扫码，查看合同信息</p><p>-管理员和超级管理员：扫码操作查看的二维码信息是合同的时间轴信息</p><p>-普通人员:扫码操作查看的是合同详情界面</p><p>-普通人员查看权限：部门负责人可以扫码查看部门下所有人员的合同信息</p><p>-部门成员只能扫码查看自己的合同详情信息</p></li></ul><p><img src="'+r+'" alt="如图所示"></p><h4 id="_6-新增合同详情" tabindex="-1">6.新增合同详情 <a class="header-anchor" href="#_6-新增合同详情" aria-label="Permalink to &quot;6.新增合同详情&quot;">​</a></h4><ul><li><p>乙方信息：来源于采购管理,供应商列表中添加的客户信息</p><p>-显示关联图标的代表这个公司有关联的子公司</p></li><li><p>关联公司：供方/需方可通过下拉框选择关联公司，同时会根据选择的关联公司，进行信息的更换</p><p>-使用关联公司时，签章时所用的印章为关联公司印章。（关联公司印章也需要设置后对人员进行授权）</p></li><li><p>乙方联系人 : 来源于供应商列表中添加的联系人(可添加多个联系人)</p></li><li><p>语言:可选择中文/英文</p></li><li><p>类型 : 来源于财务管理,汇率税率列表中添加的汇率税率信息</p></li><li><p>选择产品 : 产品来源于所添加甲方公司产品列表中的产品（可输入产品点击&quot;对号&quot;图标创建产品字段）</p></li><li><p>批量导入：可批量导入产品（先下载模板Excel进行编辑导入即可）</p></li><li><p>产品查询：支持查询已添加的产品信息</p></li><li><p>批量删除：勾选序号前的勾选框方可批量删除已添加的产品，或点击删除图标单独删除</p></li><li><p>小眼睛图标：指的是页面中需方/供方列表中的小眼睛图标，默认全展示，可选择关闭或者打开（如果关闭对方将无法看到这条信息，包括打印和下载都不展示）</p></li><li><p>小笔图标：文字傍边带有小笔图标的方可编辑</p></li><li><p>下载图标：点击下载图标可下载当前页面内容</p></li><li><p>打印图标：点击可打印当前页面的信息</p></li><li><p>使用提示：点击使用提示可弹出弹窗，在弹窗中显示动图，可切换查看对应功能的使用（新增字段，批量修改价格，调整宽度，签章显示，签章不显示）</p></li><li><p>货期：点击选择货期时间，不添加在签章时会提醒</p></li><li><p>内部型号：点击选择内部型号（选择自己公司对应的产品，物料）</p></li><li><p>历史报价 : 跟同个公司询价过同个产品时，如果再次询价就会显示之前的产品历史报价信息</p></li><li><p>历史成交价 : 跟同个公司成交过这个产品，成功以后再次询价时会显示之前的产品历史成交价</p></li><li><p>单价/总计小数点位数显示：根据汇率税率列表中设置的小数位数显示小数位数</p><p>-（例如：设置的小数位数是2位，产品列表中单价，总价显示的金额位数是两位）</p></li><li><p>总计 : 是所添加的产品单价的总计(支持更改单价添加公式(加 , 减 , 乘(乘的是百分比，1就是0.01) 输入数值)</p></li><li><p>字段更改 : 在添加产品信息以后可以悬浮对应的产品信息如果出现&quot;更改的小笔图标&quot;就代表可以更改这个产品的信息内容,或者双击也可以更改</p></li><li><p>合同附件：点击可上传合同附件，支持删除/下载</p></li><li><p>抄送：下方文本框内所填写的信息会发送给所勾选的抄送对象</p><p>-文本框所编辑的条款需要使用时记得勾选条款前面的勾选框才能显示出来</p></li><li><p>存为模板 : 如果点击存为模板在模板列表中显示所存的模板</p></li><li><p>签章：如果点击签章在选择合同章确认以后,在合同列表显示，（签章之前需填写货期）</p></li><li><p>保存：点击保存,在合同列表显示状态为 &quot;未签章&quot;，点击详情可进去签章</p><p>-编辑合同信息的时候，可以将合同暂存下来， 状态是未签章</p></li></ul><p><img src="'+i+'" alt="如图所示"></p><h4 id="_7-新增合同使用ai进行排版优化" tabindex="-1">7.新增合同使用AI进行排版优化 <a class="header-anchor" href="#_7-新增合同使用ai进行排版优化" aria-label="Permalink to &quot;7.新增合同使用AI进行排版优化&quot;">​</a></h4><ul><li>采购合同界面，点击新增合同后，进入合同详情界面，右上角有AI排版优化按键标识</li></ul><p><img src="'+s+'" alt="如图所示"></p><ul><li>不选择AI排版优化时，按键图标置灰，打印时正常使用现有正文内容</li></ul><p><img src="'+h+'" alt="如图所示"></p><ul><li>点击AI排版优化按键，按键图标变成绿色，弹窗“AI 进行排版优化预计需要10~15秒哦~”用以提示客户 <ul><li>点击“不了”选项，则不使用AI排版优化，打印时正常使用现有正文内容</li><li>点击“已知晓”选项，则使用AI排版优化，打印时会根据正文内容进行排版，使得打印内容更加整洁清晰</li></ul></li></ul><p><img src="'+u+'" alt="如图所示"></p><h4 id="_8-添加付款" tabindex="-1">8.添加付款 <a class="header-anchor" href="#_8-添加付款" aria-label="Permalink to &quot;8.添加付款&quot;">​</a></h4><ul><li>点击添加付款，在弹窗里面可以看到已添加的付款信息，可以再次添加，输入付款金额、备注、点击确认（系统会查询到与该客户另外的合同，在表单里面也可继续添加付款）</li></ul><h4 id="_9-付款状态" tabindex="-1">9.付款状态 <a class="header-anchor" href="#_9-付款状态" aria-label="Permalink to &quot;9.付款状态&quot;">​</a></h4><ul><li><p>分为：确认，已确认，退回，指的是当添加付款信息以后，需要在财务部门的合同列表中确认收款信息</p><p>-确认中：如果财务没有得到确认就显示 确认中</p><p>-已确认：如果财务确认同意了显示 ”已确认“</p><p>-退回：如果财务退回了显示 ”退回“ （退回会有标记退回的原因，可修改在次提交）</p></li></ul><p><img src="'+n+'" alt="如图所示"></p><h4 id="_10-提交发票" tabindex="-1">10.提交发票 <a class="header-anchor" href="#_10-提交发票" aria-label="Permalink to &quot;10.提交发票&quot;">​</a></h4><ul><li>提交发票：点击提交发票，在弹窗里面可以看到已添加的发票信息，可以再次添加，输入发票金额，备注，点击确认（系统会查询到与该客户的另外合同，在表单里面也可以继续提交发票）</li></ul><h4 id="_11-发票状态" tabindex="-1">11.发票状态 <a class="header-anchor" href="#_11-发票状态" aria-label="Permalink to &quot;11.发票状态&quot;">​</a></h4><ul><li><p>分为:确认中，已确认，退回，指的是当申请发票以后，需要在财务部门的合同列表中确认申请发票的信息</p><p>-确认中：如果财务没得到确认就显示 ”确认中“</p><p>-已确认：如果确认同意了显示 ”已确认“</p><p>-退回：如果退回了显示 ”退回“ （退回会有标记退回的原因，可修改在次提交）</p></li></ul><p><img src="'+c+'" alt="如图所示"></p><h1 id="采购明细" tabindex="-1">采购明细 <a class="header-anchor" href="#采购明细" aria-label="Permalink to &quot;采购明细&quot;">​</a></h1><blockquote><p>可在 “采购合同”列表切换 “采购明细”, 采购人员能够从多维度查看历史采购产品的信息数据</p></blockquote><h4 id="_1-采购明细" tabindex="-1">1.采购明细 <a class="header-anchor" href="#_1-采购明细" aria-label="Permalink to &quot;1.采购明细&quot;">​</a></h4><ul><li><p>采购明细列表查询：支持产品编号，合同单号，公司名称，产品/型号，采购员，合同时间等多维度进行数据筛选</p></li><li><p>数据来源：已签章完成的合同会生成采购明细</p></li><li><p>采购总额：显示采购的总金额，点击可查看采购总额的详情</p><p>-超级用户/管理员 能查看所有数据</p><p>-部门负责人岗位的人员，查看部门下所有人员的数据</p><p>-非部门负责人岗位的人员，查看自己的数据</p></li><li><p>已付款金额：显示已经付款的金额</p></li><li><p>未付款金额：显示未付款的金额</p></li><li><p>采购明细数据记录和删除</p><p>-采购方签章后，生成采购记录</p><p>-销售方管理员点击合同作废后，删除采购方对应合同的明细记录</p><p>-销售方取消后，删除销售方该合同的明细记录</p><p>-销售方退回后，删除采购方该合同的明细记录</p><p>-临时客户退回后， 删除 采购方 针对该合同 的 价格记录。（临时客户: 未使用用户端系统，但对方联系人允许登录销售方系统的人员）</p></li></ul><h4 id="_2-批量导入" tabindex="-1">2.批量导入 <a class="header-anchor" href="#_2-批量导入" aria-label="Permalink to &quot;2.批量导入&quot;">​</a></h4><ul><li><p>1.点击批量导入，先下载模板（注意下载的模板只适用于批量导入采购明细里面上传的模板)</p></li><li><p>2.点开下载的模板进行编辑（编辑时请阅读表格上面的提示文案，以防导入时出现错误，从而无法导入）</p></li><li><p>3.点击或者拖拽所保存的模板（只有在采购明细列表的批量编辑中下载的模板才能上传，其他无效）进行上传</p></li><li><p>4.上传成功会弹出显示上传的数据，可选择性导入或者一键导入（如果无法导入，请滑动到页面最后，查看提示信息，可能存在编辑时出现的错误，需从新更改再次上传）</p></li><li><h4 id="_3-导出" tabindex="-1">3.导出 <a class="header-anchor" href="#_3-导出" aria-label="Permalink to &quot;3.导出&quot;">​</a></h4></li><li><p>先点击导出图标，触发勾选框</p><p>-可手动输入n条导出，或手动勾选导出</p></li></ul><p><img src="'+d+'" alt="如图所示"></p>',41)]))}const I=a(_,[["render",q]]);export{A as __pageData,I as default};
